verdict("HI7", "non tranchée", "Ensemble C : FPR@95 msp 0,8697 ; C64_fam_negent 0,8489 : baisse de 0,0207, IC95 [−0,013 ; 0,055], Wilcoxon p = 0,89, signes 11/14, permutation p = 0,94 : le seuil 0,05 n'est ni atteint ni exclu.", F7)
